package com.godjiismp.mixin;
import com.godjiismp.skills.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.damagesource.DamageSource;import net.minecraft.world.entity.Entity;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.entity.projectile.Projectile;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.injection.At;import org.spongepowered.asm.mixin.injection.ModifyVariable;
@Mixin(LivingEntity.class) public abstract class SkillDamageMixin {@ModifyVariable(method="hurt",at=@At("HEAD"),argsOnly=true,index=2) private float godjiismp$applySkillDamage(float amount,DamageSource source){LivingEntity target=(LivingEntity)(Object)this;if(target.level().isClientSide)return amount;Entity attacker=source.getEntity();if(attacker instanceof Projectile projectile)attacker=projectile.getOwner();if(attacker instanceof ServerPlayer player&&(!(target instanceof Player)||SkillsConfig.pvpAttackBonus))amount*=1.0f+(float)(Skills.level(player,0)*SkillsConfig.attackPerLevel);if(target instanceof ServerPlayer player){boolean fromPlayer=attacker instanceof Player;if(!fromPlayer||SkillsConfig.pvpDefenseReduction)amount*=1.0f-(float)(Skills.level(player,1)*SkillsConfig.defensePerLevel);if(source.is(net.minecraft.world.damagesource.DamageTypes.FALL))amount*=1.0f-(float)(Skills.level(player,5)*SkillsConfig.fallPerLevel);}return Math.max(0,amount);}}
